#include <stdint.h>

int main(void)
{
    /*
    Enable GPIOA peripheral for LED
    */
    volatile uint32_t *rcc = (volatile uint32_t *)0x40023830;
    *rcc |= 1U;
    
    /*
    Configure PA5 as output by accessing GPIOA_MODER register
    */
    volatile uint32_t *gpio_a_moder = (volatile uint32_t *)0x40020000;
    uint32_t shift = 5U * 2U;
    // Clear the desired bit field
    *gpio_a_moder &= ~(3U << shift);
    *gpio_a_moder |= (1U << shift);

    /*
    Turn on green LED (LD2, PA5) by accessing GPIOA_ODR register
    */
    volatile uint32_t *gpioa_odr = (volatile uint32_t *)0x40020014;
    *gpioa_odr |= (1U << 5);
    
    for(;;);
}
